sys_script_client.script:
function onSubmit() {
    var leaveType = g_form.getValue('leave_type'); // Replace with your exact field name
    var startDateStr = g_form.getValue('start_date');
    var endDateStr = g_form.getValue('end_date');

    // Proceed only if all fields have values and it is Sick Leave
    if (leaveType === 'sick' && startDateStr !== '' && endDateStr !== '') {

        var startMs = getDateFromFormat(startDateStr, g_user_date_format);
        var endMs = getDateFromFormat(endDateStr, g_user_date_format);

        var diffInMs = endMs - startMs;
        var diffInDays = Math.round(diffInMs / (1000 * 60 * 60 * 24)) + 1;

        if (diffInDays > 2) {

            // Check if the specific attachment field/variable is empty
            var attachmentProvided = g_form.getValue('document_attachment');

            if (!attachmentProvided || attachmentProvided === 'false') {
                // Display error at the top of the form
                g_form.addErrorMessage('A medical certificate is required for Sick Leave exceeding 2 days. Please upload it before submitting.');

                // Returning false aborts the form submission
                return false; 
            }
        }
    }

    // Allow submission if conditions are met or it's not a >2 day sick leave
    return true; 
}
